The plane may be a **face** of the solid, so the triangle sits on the surface.

[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (A) at (0,0);
\coordinate (B) at (4.5,0);
\coordinate (C) at (4.5,3);
\coordinate (D) at (0,3);
\coordinate (A2) at (1.559,0.9);
\coordinate (B2) at (6.059,0.9);
\coordinate (C2) at (6.059,3.9);
\coordinate (D2) at (1.559,3.9);
\fill[blue!12] (A)--(B)--(C)--cycle;
\draw (A)--(B)--(C)--(D)--cycle;
\draw (B)--(B2)--(C2)--(C);
\draw (D)--(D2)--(C2);
\draw[dashed] (A)--(A2);
\draw[dashed] (A2)--(B2);
\draw[dashed] (A2)--(D2);
\draw[blue,thick] (A)--(C);
\coordinate (ra) at ($(B)!0.32cm!(A)$);
\coordinate (rb) at ($(B)!0.32cm!(C)$);
\draw (ra)--($(ra)+(rb)-(B)$)--(rb);
\node[below left] at (A) {$P$};
\node[below right] at (B) {$Q$};
\node[above left] at (C) {$R$};
\end{tikzpicture}
[/tikz]

It may instead be a **vertical slice** cutting through the inside of the solid.

[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (A) at (0,0);
\coordinate (B) at (4.5,0);
\coordinate (B2) at (6.752,1.3);
\coordinate (A2) at (2.252,1.3);
\coordinate (At) at (0,3.5);
\coordinate (Bt) at (4.5,3.5);
\coordinate (B2t) at (6.752,4.8);
\coordinate (A2t) at (2.252,4.8);
\fill[blue!12] (A)--(B2)--(B2t)--cycle;
\draw (A)--(B)--(B2)--(B2t);
\draw (A)--(At);
\draw (B)--(Bt);
\draw (At)--(Bt)--(B2t)--(A2t)--cycle;
\draw[dashed] (A)--(A2);
\draw[dashed] (A2)--(B2);
\draw[dashed] (A2)--(A2t);
\draw[blue,thick] (A)--(B2);
\draw[blue,thick] (A)--(B2t);
\draw[blue,thick] (B2)--(B2t);
\coordinate (sa) at ($(B2)!0.3cm!(A)$);
\coordinate (sb) at ($(B2)!0.3cm!(B2t)$);
\draw (sa)--($(sa)+(sb)-(B2)$)--(sb);
\node[below left] at (A) {$P$};
\node[below right] at (B2) {$Q$};
\node[above right] at (B2t) {$R$};
\end{tikzpicture}
[/tikz]

